	u, err := url.Parse(realm)
	if err != nil {
		return nil
	}
	reg, _ := url.Parse(registryURL)
	switch {
	case u.Scheme == "https":
		return nil
	case u.Scheme == "http" && (reg == nil || reg.Scheme != "https"):
		return nil
	case u.Hostname() == "":
		return errInsecureTokenRealm
	}
	return fmt.Errorf("%w (%s)", errInsecureTokenRealm, u.Host)
